 "path": "semantic_field.inference.chunks",
 "query": {
 "sparse_vector": {
 "inference_id": "code-wave_inference",
 "field": "semantic_field.inference.chunks.embeddings",
 "query": "holidays"
 }
 }
 }
 }
 }
 },
 {
 "standard": {
 "query": {
 "multi_match": {
 "query": "holidays",
 "fields": [
 "text_field.synonyms"
